<template>
 <view class="phone-entry">
  <view v-if="account.authenticated" class="signed-in"><view><text class="signed-label">手机号已登录</text><text class="phone-mask">{{account.masked_phone}}</text><text class="sync-state">{{syncError||syncState}}</text></view><button @click="logout">退出</button></view>
  <view v-else class="login-entry"><button @click="openDialog">手机号登录</button></view>
  <view v-if="open" class="phone-mask-overlay" @click.self="close"><view class="phone-dialog" role="dialog" aria-modal="true" aria-label="手机号验证码登录" @keydown.esc="close"><view class="dialog-head"><b>手机号验证码登录</b><button aria-label="关闭登录" @click="close">×</button></view><view class="dialog-note">登录后可在其他设备恢复常用资料</view>
   <view v-if="checking" class="phone-info">正在连接</view>
   <view v-else-if="!available" class="phone-info">手机号登录暂未开放，可继续匿名使用</view>
   <view v-else><label>手机号<input v-model="phone" type="tel" maxlength="32" placeholder="国际区号＋手机号，如 +852 91234567" placeholder-style="color:#718096" autocomplete="tel" @input="clearChallenge"/></label><view class="code-row"><label>验证码<input v-model="code" type="number" maxlength="10" placeholder="输入短信验证码" placeholder-style="color:#718096" autocomplete="one-time-code"/></label><button :disabled="sending||remaining>0||!phone.trim()" @click="requestCode">{{remaining>0?remaining+' 秒后重发':sending?'发送中…':'获取验证码'}}</button></view><button class="verify-button" :disabled="sending||verifying||!challengeId||!code.trim()" @click="verify">{{verifying?'登录中…':'验证并登录'}}</button></view>
   <view v-if="message" class="login-message" role="alert">{{message}}</view><button v-if="!checking&&!available" class="continue-button" @click="close">继续匿名使用</button><text v-else class="anonymous-link" @click="close">暂不登录</text>
  </view></view>
 </view>
</template>
<script setup>
import {ref,watch,onMounted,onBeforeUnmount,nextTick} from 'vue'
import {authRequest,setSessionToken,sessionToken} from '../utils/pilot-session.js'
const props=defineProps({profile:{type:Object,required:true}})
const emit=defineEmits(['restore'])
const account=ref({authenticated:false}),available=ref(false),open=ref(false),checking=ref(false),sending=ref(false),verifying=ref(false),message=ref(''),phone=ref(''),code=ref(''),challengeId=ref(''),remaining=ref(0),syncState=ref(''),syncError=ref('')
let countdown=null,saveTimer=null,disposed=false,hydrating=false,saveGeneration=0
function close(){if(verifying.value)return;open.value=false;phone.value='';code.value='';challengeId.value='';message.value=''}
function clearChallenge(){challengeId.value='';code.value=''}
async function openDialog(){open.value=true;checking.value=true;message.value='';try{available.value=(await authRequest('auth/phone/config')).available}catch(e){message.value=e.message}finally{checking.value=false}}
async function loadAccount(){const identity=sessionToken.value;try{const result=await authRequest('auth/me');if(disposed||identity!==sessionToken.value)return;account.value=result;available.value=result.available;if(result.authenticated&&Object.keys(result.profile||{}).length){hydrating=true;emit('restore',result.profile);await nextTick();hydrating=false;syncState.value='常用资料已加载'}}catch(e){if(disposed||identity!==sessionToken.value)return;if(e.status===401&&sessionToken.value.startsWith('ph_')){account.value={authenticated:false};try{setSessionToken((await authRequest('participants',{})).token)}catch{syncError.value='连接暂时中断，可稍后重试'}}else syncError.value=e.message}}
async function requestCode(){if(sending.value||remaining.value>0)return;sending.value=true;message.value='';try{const result=await authRequest('auth/phone/request',{phone:phone.value});challengeId.value=result.challenge_id;remaining.value=result.retry_after;clearInterval(countdown);countdown=setInterval(()=>{remaining.value=Math.max(0,remaining.value-1);if(!remaining.value)clearInterval(countdown)},1000);message.value='验证码已发送'}catch(e){message.value=e.message}finally{sending.value=false}}
async function verify(){if(verifying.value)return;verifying.value=true;message.value='';try{const result=await authRequest('auth/phone/verify',{phone:phone.value,code:code.value,challenge_id:challengeId.value});if(disposed)return;setSessionToken(result.token);account.value=result;hydrating=true;if(Object.keys(result.profile||{}).length)emit('restore',result.profile);await nextTick();hydrating=false;verifying.value=false;close();syncState.value='已登录';if(!Object.keys(result.profile||{}).length)await saveProfile()}catch(e){message.value=e.message}finally{verifying.value=false}}
async function saveProfile(){if(!account.value.authenticated||disposed)return;const generation=++saveGeneration;syncState.value='保存中';syncError.value='';try{await authRequest('auth/profile',{profile:props.profile});if(disposed||generation!==saveGeneration)return;syncState.value='常用资料已同步'}catch(e){if(disposed||generation!==saveGeneration)return;syncState.value='';syncError.value=e.status===401?'登录已过期，资料仍保存在本地':e.message}}
async function logout(){try{clearTimeout(saveTimer);saveGeneration++;const result=await authRequest('auth/logout',{});setSessionToken(result.token);account.value={authenticated:false};syncState.value='';syncError.value=''}catch(e){syncError.value=e.message}}
watch(()=>props.profile,()=>{if(hydrating||!account.value.authenticated)return;clearTimeout(saveTimer);saveTimer=setTimeout(saveProfile,700)},{deep:true})
watch(sessionToken,()=>{clearTimeout(saveTimer);saveGeneration++;loadAccount()})
onMounted(loadAccount)
onBeforeUnmount(()=>{disposed=true;clearInterval(countdown);clearTimeout(saveTimer)})
</script>
<style scoped>
.phone-entry{margin:0 0 16px}.login-entry,.signed-in{display:flex;justify-content:space-between;align-items:center;gap:14px;padding:13px 14px;border:1px solid #354457;background:#0e1824;border-radius:9px}.login-title,.signed-label{display:block;font-size:12px;color:#cfdaea}.login-note,.sync-state{display:block;font-size:10px;color:#8d9fb7;margin-top:5px}.phone-mask{color:#bee0a1;font-size:12px;margin-left:10px}.signed-in>view{display:flex;align-items:baseline;flex-wrap:wrap}.sync-state{width:100%}.phone-entry button{margin:0;border:1px solid #768f57;background:#b9f4770d;border-radius:7px;color:#c7e8a9;font-size:12px;line-height:1.5;padding:8px 12px;white-space:nowrap}.signed-in button{border-color:#405169;color:#9caec5;background:none;font-size:11px}.phone-mask-overlay{position:fixed;inset:0;z-index:100;display:flex;align-items:center;justify-content:center;padding:20px;background:#02060bd6;backdrop-filter:blur(6px)}.phone-dialog{width:100%;max-width:380px;padding:22px;background:#141e2b;border:1px solid #3d4d64;border-radius:15px;box-shadow:0 24px 80px #0008}.dialog-head{display:flex;justify-content:space-between;align-items:center;gap:14px}.dialog-head b{font-size:17px;color:#e4ecf6}.dialog-head button{border:0;background:none;color:#94a6bd;font-size:23px;padding:0 5px}.dialog-note{color:#94a6bd;font-size:11px;line-height:1.8;margin:8px 0 21px}.phone-info{color:#aebed3;font-size:13px;line-height:1.9;padding:15px;background:#0d1622;border-radius:8px}.phone-dialog label{display:block;color:#adbed4;font-size:12px;min-width:0}.phone-dialog input{width:100%;box-sizing:border-box;height:43px;padding:10px 11px;color:#e1eaf5;border:1px solid #40516a;background:#0b141f;border-radius:7px;margin-top:8px;font-size:13px}.code-row{display:flex;align-items:flex-end;gap:10px;margin-top:17px}.code-row label{flex:1}.code-row button{height:43px;padding:10px;font-size:11px;border-color:#4b6143}.phone-dialog .verify-button,.phone-dialog .continue-button{display:block;width:100%;margin-top:20px;padding:11px 12px;font-size:13px;background:#b9f477;color:#14200d;border-color:#b9f477;font-weight:650}.login-message{color:#e6c488;font-size:11px;margin-top:13px;line-height:1.7}.anonymous-link{display:block;text-align:center;font-size:11px;color:#8b9fb9;margin-top:17px;cursor:pointer}.phone-entry button[disabled]{opacity:.4;cursor:not-allowed}.phone-entry button:focus-visible{outline:2px solid #b9f477;outline-offset:2px}@media(max-width:400px){.phone-dialog{padding:19px}.login-entry{gap:10px}.login-title{font-size:11px}.login-entry button{font-size:11px;padding:8px 10px}}

/* The parent places this entry beside the basic-information heading. */
.phone-entry{margin:0;min-width:0}.login-entry,.signed-in{margin:0;padding:0;border:0;border-radius:0;background:none;gap:9px}.login-entry>button{padding:5px 10px;font-size:11px;line-height:1.5;min-height:28px}.signed-in>view{display:flex;align-items:center;flex-wrap:nowrap;gap:6px;min-width:0}.signed-label{font-size:10px;white-space:nowrap}.phone-mask{margin:0;font-size:10px;white-space:nowrap}.sync-state{display:inline;width:auto;max-width:130px;margin:0;font-size:9px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.signed-in>button{padding:4px 7px;font-size:10px}@media(max-width:500px){.sync-state{max-width:70px}.signed-label{display:none}.signed-in>view{gap:4px}}
</style>
